INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('contract-risk-reviewer', 'Contract Risk Reviewer', 'Upload a contract to get a clause-by-clause risk review, red flags, missing protections and suggested wording to negotiate.', 'Legal & Compliance', ARRAY['Contracts', 'Document Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('gst-reconciliation-check', 'GST Reconciliation Check', 'Upload your purchase register and GSTR-2B to find mismatches, missing invoices, input credit at risk and supplier follow-ups.', 'Finance & Accounting', ARRAY['GST', 'Accounting'], 'featured', true, false, false, NULL, 0, ARRAY['Legal & Compliance']),
  ('compliance-calendar-builder', 'Compliance Calendar Builder', 'Tell us your business type and registrations to get a 12-month compliance calendar for GST, TDS, ROC, PF, ESI and licences.', 'Legal & Compliance', ARRAY['Compliance', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Finance & Accounting']),
  ('company-registration-guide', 'Company Registration Guide', 'Choose between proprietorship, partnership, LLP and private limited, then get the exact registration steps, documents and post-registration tasks.', 'Legal & Compliance', ARRAY['Company Formation', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('will-writer', 'Will Writer', 'A guided conversation that turns your wishes into a clear draft will, with executor, guardians, asset list and signing instructions.', 'Legal & Compliance', ARRAY['Estate Planning', 'Legal Drafts'], 'featured', true, false, false, NULL, 0, ARRAY['Personal', 'Money & Planning']),
  ('property-paper-checker', 'Property Paper Checker', 'Upload sale deed, title chain, approvals and tax receipts to get a document checklist, red flags and questions before you buy.', 'Legal & Compliance', ARRAY['Real Estate', 'Due Diligence'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('rental-dispute-helper', 'Rental Dispute Helper', 'For tenants or landlords: understand your position on deposit, rent, repairs or eviction, and get a step-by-step plan and letters.', 'Legal & Compliance', ARRAY['Rent', 'Disputes'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('consumer-complaint-builder', 'Consumer Complaint Builder', 'Build a strong consumer complaint: timeline, evidence list, notice to the company, helpline complaint and a draft for the consumer commission.', 'Legal & Compliance', ARRAY['Consumer Rights', 'Letters'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('trademark-readiness-kit', 'Trademark Readiness Kit', 'Get your brand ready to file a trademark: name strength check, classes to consider, search steps, user evidence and filing checklist.', 'Legal & Compliance', ARRAY['Trademark', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('dpdp-privacy-kit', 'DPDP Privacy Kit', 'Get ready for India''s data protection law: data map, privacy notice, consent text, retention rules, breach plan and staff checklist.', 'Legal & Compliance', ARRAY['Privacy', 'Compliance'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('labour-law-compliance-audit', 'Labour Law Compliance Audit', 'A guided audit of your employment practices: registrations, wages, PF and ESI, leave, contracts and records, with a fix list.', 'Legal & Compliance', ARRAY['HR', 'Compliance'], 'featured', true, false, false, NULL, 0, ARRAY['HR & Staffing']),
  ('court-case-organiser', 'Court Case Organiser', 'Upload your case papers to get a case summary, timeline, list of documents, hearing history, next steps and questions for your lawyer.', 'Legal & Compliance', ARRAY['Litigation', 'Document Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('business-licence-finder', 'Business Licence Finder', 'Find which licences and registrations your business needs in your state, the order to apply, documents and where to apply.', 'Legal & Compliance', ARRAY['Licences', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('accident-claim-helper', 'Accident Claim Helper', 'After a road accident: what to do now, documents, insurance claim steps, compensation claim route and letters, in one plan.', 'Legal & Compliance', ARRAY['Insurance', 'Claims'], 'featured', true, false, false, NULL, 0, ARRAY['Money & Planning']),
  ('rti-application-studio', 'RTI Application Studio', 'Draft a sharp RTI application that gets answers: right department, precise questions, fee steps, first appeal and second appeal drafts.', 'Legal & Compliance', ARRAY['RTI', 'Letters'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('term-sheet-explainer', 'Term Sheet Explainer', 'Upload an investor term sheet to get every clause explained, founder-friendliness scored, dilution worked out and points to negotiate.', 'Legal & Compliance', ARRAY['Fundraising', 'Contracts'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('esop-plan-designer', 'ESOP Plan Designer', 'Design an employee stock option plan: pool size, grants by role, vesting, exercise rules, an offer letter section and an employee FAQ.', 'Legal & Compliance', ARRAY['ESOP', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy', 'HR & Staffing']),
  ('import-export-starter-kit', 'Import-Export Starter Kit', 'Start importing or exporting: registrations, product classification steps, documents, costing sheet, buyer search and first-shipment checklist.', 'Legal & Compliance', ARRAY['Trade', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy', 'Online Selling']),
  ('senior-citizen-benefits-finder', 'Senior Citizen Benefits Finder', 'Find benefits a senior citizen may claim: pensions, health schemes, tax points, travel concessions, savings schemes and how to apply.', 'Home, Family & Travel', ARRAY['Government Schemes', 'Elder Care'], 'featured', true, false, false, NULL, 0, ARRAY['Legal & Compliance', 'Money & Planning']),
